edits.replace:
* { box-sizing: border-box; }
:root { color-scheme: light; --paper: #f5f0e3; --ink: #283c34; --muted: #59675c; --line: #d6cbb4; --red: #a14535; --serif: 'Songti SC', 'Noto Serif CJK SC', SimSun, serif; font-family: system-ui, 'Microsoft YaHei', sans-serif; }
body { margin: 0; min-height: 100svh; background: radial-gradient(ellipse at 40% 0%, #fcf8ec, transparent 76%), #eee6d5; color: var(--ink); }
#village { width: min(1312px, 100%); margin: 0 auto; padding: clamp(16px, 4vw, 56px) clamp(12px, 3.5vw, 48px) 20px; }
h1, h2, p { margin: 0; }
.hud { display: flex; align-items: center; justify-content: space-between; gap: 14px; margin-bottom: 24px; }
.brand { display: flex; align-items: center; gap: clamp(8px, 1.5vw, 18px); }
.seal { display: grid; align-content: center; text-align: center; flex: none; width: 38px; height: 52px; border: 1px solid var(--red); box-shadow: inset 0 0 0 2px var(--paper), inset 0 0 0 3px var(--red); color: var(--red); font: bold 15px/1.15 var(--serif); border-radius: 2px 5px 3px 4px; }
.chapter { color: var(--red); font-size: 12px; font-weight: 700; letter-spacing: .12em; margin-bottom: 4px; }
h1 { font: 800 clamp(32px, 5vw, 61px)/1.06 var(--serif); letter-spacing: .08em; white-space: nowrap; }
.supplies { display: grid; grid-template-columns: repeat(3, 1fr); align-items: center; background: #fcf8edaa; border: 1px solid var(--line); padding: 8px 2px; font-size: 12px; }
.supplies div { display: grid; gap: 3px; text-align: center; padding: 0 clamp(7px, 1.8vw, 23px); color: var(--muted); white-space: nowrap; }
.supplies div + div { border-left: 1px solid var(--line); }
.supplies b { color: var(--ink); font: bold clamp(18px, 2.2vw, 27px)/1.08 Georgia, serif; font-variant-numeric: tabular-nums; }
.layout { display: grid; grid-template-columns: minmax(0, 1fr) minmax(246px, 285px); gap: clamp(12px, 2vw, 24px); align-items: stretch; }
.world { min-width: 0; border: 1px solid #879284; background: #253e36; box-shadow: 0 12px 28px #50442a20; align-self: start; }
.map { position: relative; aspect-ratio: 16 / 9; isolation: isolate; overflow: hidden; background: #a4b5a5; }
#surface, #sites { position: absolute; inset: 0; }
#sites { pointer-events: none; }
.map-label { pointer-events: none; position: absolute; top: 12px; left: 12px; display: flex; align-items: center; gap: 6px; font-size: 11px; font-weight: 700; padding: 5px 8px; color: #304637; background: #faf5dfed; border: 1px solid #fff7df; box-shadow: 0 2px 8px #35493c30; }
.map-label span { width: 6px; height: 6px; background: var(--red); transform: rotate(45deg); }
.map-footer { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 3px 12px; min-height: 44px; color: #f5e8ce; font-size: 12px; }
button { font: inherit; color: inherit; cursor: pointer; touch-action: manipulation; }
button:disabled { cursor: default; }
button:focus-visible { outline: 2px solid #ab492e; outline-offset: 3px; }
[hidden] { display: none !important; }
#sound { background: transparent; border: 0; min-height: 40px; padding: 0 6px; }
#sound:hover { text-decoration: underline; }
.plot { position: absolute; display: grid; justify-items: center; min-width: 45px; min-height: 44px; align-content: center; transform: translate(-50%, -51%); border: 0; padding: 0; background: transparent; pointer-events: auto; }
.marker { width: 15px; height: 15px; background: #ffedbb; border: 3px solid #345246; transform: rotate(45deg); box-shadow: 0 0 0 1px #fff3cc; margin-bottom: 5px; }
.plot .name, #guest { white-space: nowrap; background: #253e35; color: #fff5dc; border: 1px solid #e3d0a4; font-size: clamp(10px, 1.1vw, 13px); padding: 2px 6px; box-shadow: 0 2px 6px #20382b44; }
.plot:hover .name, .plot[aria-pressed='true'] .name, #guest:not(:disabled):hover { background: #873f2d; }
.plot[aria-pressed='true'] .marker { background: #b65035; border-color: #ffedbb; }
.landing { position: absolute; left: 53%; top: 77%; }
#guest { min-height: 36px; transform: translateY(-50%); border-radius: 2px; }
#guest:disabled { background: #f2e6c5; color: #354b3e; border-color: #d4b782; }
.journal { min-width: 0; display: flex; flex-direction: column; padding: clamp(14px, 2vw, 24px); background: #fcf8ed; border: 1px solid var(--line); border-top: 3px solid #617360; }
.journal-head { display: flex; gap: 8px; justify-content: space-between; padding-bottom: 12px; border-bottom: 1px solid var(--line); font-size: 12px; font-weight: 700; color: var(--muted); letter-spacing: .08em; }
#progress { font: bold 13px Georgia, serif; color: var(--red); }
#message { margin-top: clamp(12px, 2vw, 24px); }
h2 { font: bold clamp(23px, 2.5vw, 32px)/1.2 var(--serif); }
#hint { font-size: 14px; color: var(--muted); line-height: 1.65; margin-top: 10px; }
.actions { display: flex; flex-wrap: wrap; gap: 8px; margin: 15px 0; }
.actions:empty { display: none; }
.actions button { padding: 7px 11px; min-height: 44px; background: #f5eedf; border: 1px solid #cdbf9f; font-size: 14px; }
.actions .primary { flex: 1; background: #345648; color: #fff5de; border-color: #345648; font-weight: 700; }
.actions .primary:hover { background: #254236; }
.steps { list-style: none; margin: auto 0 0; padding: 12px 0 0; border-top: 1px solid var(--line); display: grid; gap: 10px; font-size: 13px; color: var(--muted); }
.steps li { display: flex; align-items: center; gap: 9px; }
.steps li[aria-current='step'] { color: var(--ink); font-weight: 700; }
.step-mark { display: grid; place-content: center; width: 16px; height: 16px; border: 1px solid #a8aa95; border-radius: 50%; font-size: 10px; }
.steps [aria-current] .step-mark { border: 4px solid #c4d0b8; background: #345648; }
.steps .done .step-mark { border-color: #5c7562; color: #fcf8ed; background: #5c7562; }
.help { margin-top: 14px; font-size: 12px; color: var(--muted); line-height: 1.6; }
@media (max-width: 820px) { .layout { grid-template-columns: 1fr; } .steps { grid-template-columns: repeat(3, 1fr); gap: 6px; } .steps li { gap: 4px; } .hud { margin-bottom: 14px; } }
@media (max-width: 450px) { .seal { display: none; } .steps { font-size: 11px; } .landing { top: 72%; left: 54%; } #guest { min-height: 32px; } .map-label { top: 6px; left: 6px; } }

export const PLOTS = [
  { id: 'willow', name: '柳荫', x: 206, y: 337, note: '柳荫遮住了上岸的小路。' },
  { id: 'stone', name: '石阶', x: 353, y: 397, note: '从石阶走到泊位只需几步。' },
  { id: 'reed', name: '芦湾', x: 554, y: 479, note: '芦苇挡风，湾里水势平缓。' }
];
export const buildCost = 8;
export const firstFare = 3;
export const findPlot = id => PLOTS.find(plot => plot.id === id);

export function beginWorld(saved) {
  const shed = findPlot(saved?.shed) ?? null;
  const trip = shed && ['sailing', 'arrived'].includes(saved?.trip) ? saved.trip : 'waiting';
  return { selected: null, shed, trip };
}

export function buildShed(world) {
  if (world.shed || !world.selected) return false;
  world.shed = world.selected;
  world.selected = null;
  return true;
}

export function boardGuest(world) {
  if (!world.shed || world.trip !== 'waiting') return false;
  world.trip = 'sailing';
  return true;
}

export const SAVE_KEY = 'mist-ferry';
const RECORD = 'first-crossing-v1';
export const readProgress = game => game.load(RECORD, null);

export function writeProgress(game, world, muted) {
  game.save(RECORD, { shed: world.shed?.id ?? null, trip: world.trip, muted });
}

import { play } from '@egret/engine/play';
import { boardGuest, beginWorld, buildCost, buildShed, firstFare, PLOTS } from './sim/world.mjs';
import { readProgress, SAVE_KEY, writeProgress } from './saves.mjs';
import { boatArt, personArt, shedArt, terrain } from './scenery.mjs';

const el = id => document.getElementById(id);
const boxes = new Map();
const art = {};
const steps = [...document.querySelectorAll('.steps li')];
const focus = node => node.focus({ preventScroll: true });
const at = (x, y) => ({ x, y });
const wait = at(481, 418);
const pier = at(447, 394);
const ramp = at(491, 351);
const homeWater = at(533, 343);
const farWater = at(795, 229);
const farPier = at(817, 210);
const farPath = at(834, 186);
const frameTime = 1.05;
const tripTime = 5.3;
let world = beginWorld();
let muted = false;
let game;
let closed = false;
let resetting = false;
let building = null;
let crossing = 0;

function mix(a, b, t) {
  const u = Math.max(0, Math.min(t, 1));
  return at(a.x + (b.x - a.x) * u, a.y + (b.y - a.y) * u);
}

function save() {
  try { writeProgress(game, world, muted); } catch { /* Keep the current session playable. */ }
}

function view() {
  if (resetting) return ['重开渡口？', '本轮搭好的船棚会收起，木料与账目将恢复到开局。', '确认重开', '返回'];
  if (world.trip === 'arrived') return ['第一趟，平安到岸', `客人已经走上北岸，付了 ${firstFare} 枚铜钱。${world.shed.name}的船棚也有了第一道灯火。`];
  if (world.trip === 'sailing') return ['船过春水', '摆渡人接客上船，正划向北岸的石埠。'];
  if (building !== null) return ['木梁立起来了', `摆渡人正在${world.shed.name}搭棚，好让渡船靠岸时有处遮雨。`];
  if (world.shed) return ['接第一位客人', `船棚已在${world.shed.name}搭好。客人在南岸木埠等船，要去对岸的村子。`, '接客开船'];
  if (world.selected) return [`在${world.selected.name}搭棚`, `${world.selected.note}用 ${buildCost} 份木料。可以改选，也可以取消。`, `动工 · ${buildCost} 木料`, '取消'];
  return ['给摆渡人搭座船棚', '船已靠岸，客人也到了。点选岸边的一处用地，先给摆渡人搭一座船棚。'];
}

function refresh() {
  const [title, hint, action, cancel] = view();
  const arrived = world.trip === 'arrived';
  const ready = world.shed && building === null;
  const count = arrived ? 3 : ready ? 2 : world.shed || world.selected ? 1 : 0;
  el('objective').textContent = title;
  el('hint').textContent = hint;
  el('timber').textContent = 12 - (world.shed ? buildCost : 0);
  el('fare').textContent = arrived ? firstFare : 0;
  el('people').textContent = arrived ? 1 : 0;
  el('progress').textContent = `${count} / 3`;
  el('river-status').textContent = arrived ? '渡船已到北岸' : world.trip === 'sailing' ? '渡船正在横渡' : '渡船系在南岸';
  el('sites').hidden = Boolean(world.shed);
  el('landing').hidden = world.trip !== 'waiting';
  el('guest').disabled = !ready;
  el('guest').textContent = ready ? '接客开船' : '等船客人';
  for (const [plot, button] of boxes) button.setAttribute('aria-pressed', String(plot === world.selected));
  for (const [i, step] of steps.entries()) {
    step.classList.toggle('done', i < count);
    step.firstElementChild.textContent = i < count ? '✓' : '';
    if (i === count) step.setAttribute('aria-current', 'step');
    else step.removeAttribute('aria-current');
  }
  el('confirm').hidden = !action;
  el('confirm').textContent = action ?? '';
  el('cancel').hidden = !cancel;
  el('cancel').textContent = cancel ?? '';
  el('again').hidden = !arrived || resetting;
  el('sound').textContent = `声音：${muted ? '关' : '开'}`;
  el('sound').setAttribute('aria-pressed', String(!muted));
}

function draw(time = 0) {
  const plot = world.shed ?? world.selected;
  for (const [item, visible] of [[art.preview, Boolean(world.selected)], [art.frame, building !== null], [art.shed, Boolean(world.shed) && building === null]]) {
    item.visible = visible;
    if (plot) { item.x = plot.x; item.y = plot.y; }
  }
  const arrived = world.trip === 'arrived';
  const sailing = world.trip === 'sailing';
  const motion = !game?.reducedMotion;
  const t = arrived ? tripTime : crossing;
  const afloat = mix(homeWater, farWater, (t - 1.3) / 2.95);
  if (sailing && t > 1.3 && t < 4.25) afloat.y -= Math.sin(Math.PI * (t - 1.3) / 2.95) * 19;
  afloat.y += motion && game ? Math.sin(time * 2.4) * 1.2 : 0;
  art.boat.x = afloat.x;
  art.boat.y = afloat.y;
  art.wake.x = afloat.x;
  art.wake.y = afloat.y;
  art.wake.visible = sailing && t > 1.3 && t < 4.25;

  const onBoat = at(afloat.x - 33, afloat.y - 8);
  const offBoat = at(afloat.x + 33, afloat.y - 9);
  let guest = wait;
  let ferryman = at(463, 380);
  if (world.shed) ferryman = building === null ? at(plot.x + 40, plot.y + 7) : mix(ferryman, at(plot.x + 40, plot.y + 7), building / frameTime);
  if (sailing || arrived) {
    const board = at(homeWater.x - 33, homeWater.y - 8);
    if (t < .52) {
      guest = mix(wait, pier, t / .52);
      ferryman = mix(ferryman, pier, t / .52);
    } else if (t < 1.3) {
      const dockWalk = mix(pier, ramp, (t - .52) / .62);
      guest = t < 1.14 ? dockWalk : mix(ramp, board, (t - 1.14) / .16);
      ferryman = t < 1.14 ? mix(pier, ramp, (t - .52) / .54) : mix(ramp, offBoat, (t - 1.14) / .16);
    } else {
      ferryman = offBoat;
      guest = t < 4.25 ? onBoat : t < 4.73 ? mix(onBoat, farPier, (t - 4.25) / .48) : mix(farPier, farPath, (t - 4.73) / (tripTime - 4.73));
    }
  }
  art.guest.x = guest.x;
  art.guest.y = guest.y;
  art.ferryman.x = ferryman.x;
  art.ferryman.y = ferryman.y;
}

function launch() {
  if (!game || building !== null || !boardGuest(world)) return;
  crossing = 0;
  if (game.reducedMotion) {
    arrive(true);
    return;
  }
  save();
  game.sfx.play('castoff', { volume: .48 });
  draw();
  refresh();
}

function arrive(moveFocus) {
  world.trip = 'arrived';
  save();
  game.sfx.play('coin', { volume: .32 });
  draw();
  refresh();
  if (moveFocus || document.activeElement === document.body) focus(el('again'));
}

function cancel() {
  const selected = world.selected;
  world.selected = null;
  const wasResetting = resetting;
  resetting = false;
  draw();
  refresh();
  if (wasResetting) focus(el('again'));
  else if (selected) focus(boxes.get(selected));
}

function confirm() {
  if (!game) return;
  if (resetting) {
    resetting = false;
    world = beginWorld();
    crossing = 0;
    save();
    draw();
    refresh();
    focus(boxes.get(PLOTS[0]));
    return;
  }
  if (world.shed) { launch(); return; }
  if (!buildShed(world)) return;
  building = game.reducedMotion ? null : 0;
  save();
  game.sfx.play('build', { volume: .55 });
  draw();
  refresh();
  if (building === null) focus(el('confirm'));
}

for (const plot of PLOTS) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'plot';
  button.style.left = `${plot.x / 960 * 100}%`;
  button.style.top = `${plot.y / 540 * 100}%`;
  button.setAttribute('aria-label', `预览${plot.name}船棚`);
  const marker = document.createElement('span');
  marker.className = 'marker';
  marker.setAttribute('aria-hidden', 'true');
  const label = document.createElement('span');
  label.className = 'name';
  label.textContent = plot.name;
  button.append(marker, label);
  boxes.set(plot, button);
  el('sites').append(button);
  button.addEventListener('click', () => {
    if (!game || world.shed) return;
    world.selected = plot;
    game.sfx.play('click', { volume: .26 });
    draw();
    refresh();
    focus(el('confirm'));
  });
}

el('confirm').addEventListener('click', confirm);
el('cancel').addEventListener('click', cancel);
el('guest').addEventListener('click', launch);
el('again').addEventListener('click', () => {
  resetting = true;
  refresh();
  focus(el('cancel'));
});
el('sound').addEventListener('click', () => {
  muted = !muted;
  game.sfx.muted = muted;
  save();
  refresh();
});
el('village').addEventListener('keydown', event => {
  if (event.key === 'Escape' && (world.selected || resetting)) {
    event.preventDefault();
    cancel();
  }
});
window.addEventListener('pagehide', event => {
  if (event.persisted) return;
  closed = true;
  if (game) void game.dispose();
});

try {
  const player = await play({
    parent: el('surface'), width: 960, height: 540, saveKey: SAVE_KEY,
    setup(g) {
      let saved;
      try { saved = readProgress(g); } catch { saved = null; }
      muted = saved?.muted === true;
      world = beginWorld(saved);
      g.sfx.muted = muted;
      g.sfx.define('build', [
        { wave: 'triangle', from: 157, to: 83, seconds: .12, decay: 7 },
        { wave: 'sine', from: 490, to: 540, seconds: .19, decay: 5 }
      ]);
      g.sfx.define('castoff', { wave: 'sine', from: 223, to: 326, seconds: .25, decay: 5 });
      terrain(g, PLOTS);
      art.preview = shedArt(g, 'preview');
      art.preview.alpha = .68;
      art.frame = shedArt(g, 'frame');
      art.shed = shedArt(g, 'ready');
      Object.assign(art, boatArt(g));
      art.guest = personArt(g, 0xa8503c, 0x754d3a);
      art.ferryman = personArt(g, 0x405f66, 0xbd9b60);
      draw();
    },
    update(dt, g) {
      if (!game) return;
      if (building !== null) {
        building += dt;
        if (building >= frameTime || game.reducedMotion) {
          building = null;
          refresh();
          if (document.activeElement === document.body) focus(el('confirm'));
        }
      }
      if (world.trip === 'sailing') {
        crossing += dt;
        if (crossing >= tripTime || game.reducedMotion) arrive(false);
      }
      draw(g.time);
    }
  });
  if (closed) await player.dispose();
  else {
    game = player;
    el('sound').disabled = false;
    refresh();
  }
} catch (error) {
  if (!closed) {
    console.error(error);
    el('objective').textContent = '渡口暂时无法开启';
    el('hint').textContent = '请刷新页面，再试一次。';
  }
}
